def coalesce(intervals):
    validated = []
    try:
        iterator = iter(intervals)
    except TypeError as exc:
        raise ValueError("intervals must be iterable") from exc

    for interval in iterator:
        try:
            pair = tuple(interval)
        except TypeError as exc:
            raise ValueError("each interval must contain exactly two integers") from exc

        if len(pair) != 2:
            raise ValueError("each interval must contain exactly two integers")

        start, end = pair
        if type(start) is not int or type(end) is not int or start >= end:
            raise ValueError("interval endpoints must be plain integers with start < end")

        validated.append((start, end))

    validated.sort()
    result = []

    for start, end in validated:
        if result and start <= result[-1][1]:
            previous_start, previous_end = result[-1]
            result[-1] = (previous_start, max(previous_end, end))
        else:
            result.append((start, end))

    return result
